Add-Type -AssemblyName System.Drawing
$pairs=@()
foreach($w in @(1366,390,844)){foreach($state in @('main','ranking','guide-basics','guide-bonuses','guide-hazards','settings-sound','settings-game','pause','result','record')){$after="$state-$w";if($state -eq 'main' -and $w -eq 390){$after='main-390-portrait'};if($state -eq 'main' -and $w -eq 844){$after='main-844-landscape'};if($state -like 'guide-*' -and $w -eq 390){if($state -ne 'guide-hazards'){continue};$after='guide-390'};$pairs+=@{before="before-$state-$w";after=$after;name="$state-$w"}}}
foreach($w in @(1366,844)){$pairs+=@{before="before-gameplay-hud-$w";after="gameplay-hud-$w";name="gameplay-hud-$w"}}
foreach($pair in $pairs){$a=[Drawing.Bitmap]::new((Join-Path $PSScriptRoot ($pair.before+'.png')));$b=[Drawing.Bitmap]::new((Join-Path $PSScriptRoot ($pair.after+'.png')));$canvas=[Drawing.Bitmap]::new($a.Width+$b.Width+12,[Math]::Max($a.Height,$b.Height)+28);$g=[Drawing.Graphics]::FromImage($canvas);$font=[Drawing.Font]::new('Arial',14);try{$g.Clear([Drawing.Color]::FromArgb(18,34,42));$g.DrawString('BEFORE / V2',$font,[Drawing.Brushes]::White,4,4);$g.DrawString('V2.1 CANDIDATE',$font,[Drawing.Brushes]::White,$a.Width+16,4);$g.DrawImageUnscaled($a,0,28);$g.DrawImageUnscaled($b,$a.Width+12,28);$canvas.Save((Join-Path $PSScriptRoot ('strip-'+$pair.name+'.png')),[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose();$canvas.Dispose();$font.Dispose();$a.Dispose();$b.Dispose()}}
Write-Output "$($pairs.Count) native before/after strips; no image resizing."
